export function tick(clock, id) {
  return { ...clock, [id]: (clock[id] || 0) + 1 };
}

export function merge(a, b) {
  const result = { ...a };
  for (const key of Object.keys(b)) {
    result[key] = Math.max(result[key] || 0, b[key]);
  }
  return result;
}

export function compare(a, b) {
  let less = false;
  let greater = false;
  const keys = new Set([...Object.keys(a || {}), ...Object.keys(b || {})]);
  for (const key of keys) {
    const x = a[key] || 0;
    const y = b[key] || 0;
    if (x < y) less = true;
    else if (x > y) greater = true;
  }
  if (less && greater) return 'concurrent';
  if (less) return -1;
  if (greater) return 1;
  return 0;
}
