import { tick } from './clock.js';

let counter = 0;

export function genId(prefix = 'el') {
  counter += 1;
  return `${prefix}-${Date.now().toString(36)}-${counter.toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
}

export function makeOp(ctx, kind, elementId, data = {}, before = null) {
  const next = tick(ctx.clock, ctx.userId);
  const op = {
    opId: genId('op'),
    roomId: ctx.roomId,
    userId: ctx.userId,
    userName: ctx.userName,
    kind,
    elementId,
    data,
    before,
    clock: ctx.clock,
    lamport: next[ctx.userId],
    ts: Date.now(),
  };
  ctx.clock = next;
  return op;
}
