import { merge as mergeClock, compare } from './clock.js';

let conflictCounter = 0;

export function snapshotOf(el) {
  return JSON.parse(JSON.stringify(el));
}

function bumpElementClock(el, op) {
  el.clock = mergeClock(el.clock || {}, op.clock || {});
  el.clock = mergeClock(el.clock, { [op.userId]: op.lamport || 0 });
  el.lastOp = { lamport: op.lamport || 0, userId: op.userId, userName: op.userName };
}

function beats(aLamport, aUser, bLamport, bUser) {
  return aLamport > bLamport || (aLamport === bLamport && String(aUser) > String(bUser));
}

function conflictRecord(op, el, type, detail, result, extra = {}) {
  conflictCounter += 1;
  return {
    id: `c-${Date.now().toString(36)}-${conflictCounter}`,
    elementId: op.elementId,
    elementType: el ? el.type : 'unknown',
    type,
    users: [...new Set([el && el.lastOp ? el.lastOp.userName : '?', op.userName])],
    userIds: [...new Set([el && el.lastOp ? el.lastOp.userId : '?', op.userId])],
    detail,
    result,
    ts: Date.now(),
    ...extra,
  };
}

function isConcurrent(el, op) {
  const rel = compare(el.clock || {}, op.clock || {});
  return rel === 'concurrent' || rel === 1;
}

export function applyOp(state, op) {
  const conflicts = [];
  state.clock = mergeClock(state.clock || {}, op.clock || {});
  state.clock = mergeClock(state.clock, { [op.userId]: op.lamport || 0 });
  const el = op.elementId ? state.elements.get(op.elementId) : null;

  switch (op.kind) {
    case 'add': {
      const element = { ...op.data.element, deleted: false, clock: {}, fieldClocks: {}, lastOp: null };
      state.elements.set(element.id, element);
      bumpElementClock(element, op);
      break;
    }
    case 'update': {
      if (!el) break;
      if (el.deleted) {
        conflicts.push(conflictRecord(op, el, 'delete-vs-update',
          '元素已被删除，又收到并发的属性修改',
          '删除优先，修改被丢弃（可从冲突面板恢复元素）',
          { deletedSnapshot: snapshotOf(el) }));
        break;
      }
      const concurrent = isConcurrent(el, op);
      const fields = Object.keys(op.data || {}).filter((f) => f !== 'id');
      const hadPrior = fields.some((f) => el.fieldClocks && el.fieldClocks[f]);
      const won = [];
      const lost = [];
      for (const field of fields) {
        const fc = (el.fieldClocks || {})[field];
        let apply = true;
        if (concurrent && fc && beats(fc.lamport, fc.userId, op.lamport || 0, op.userId)) apply = false;
        if (apply) {
          el[field] = op.data[field];
          el.fieldClocks = el.fieldClocks || {};
          el.fieldClocks[field] = { lamport: op.lamport || 0, userId: op.userId };
          won.push(field);
        } else {
          lost.push(field);
        }
      }
      if (concurrent && hadPrior) {
        conflicts.push(conflictRecord(op, el, 'concurrent-update',
          `字段 [${fields.join(', ')}] 被两个用户并发修改`,
          lost.length
            ? `按确定性规则（lamport 时间戳 + 用户ID 排序）：采用 ${op.userName} 的 [${won.join(', ') || '无'}]，保留现有 [${lost.join(', ')}]`
            : `采用 ${op.userName} 的修改（与现有修改不冲突的字段已合并）`,
          { fields, won, lost }));
      }
      bumpElementClock(el, op);
      break;
    }
    case 'move': {
      if (!el) break;
      if (el.deleted) {
        conflicts.push(conflictRecord(op, el, 'delete-vs-update',
          '元素已被删除，又收到并发的移动操作',
          '删除优先，移动被丢弃（可从冲突面板恢复元素）',
          { deletedSnapshot: snapshotOf(el) }));
        break;
      }
      const concurrent = isConcurrent(el, op);
      el.x = (el.x || 0) + (op.data.dx || 0);
      el.y = (el.y || 0) + (op.data.dy || 0);
      if (concurrent) {
        conflicts.push(conflictRecord(op, el, 'concurrent-move',
          '元素被两个用户同时移动',
          '移动采用增量叠加合并，双方位移都已生效，无操作丢失'));
      }
      bumpElementClock(el, op);
      break;
    }
    case 'delete': {
      if (!el || el.deleted) break;
      if (isConcurrent(el, op)) {
        conflicts.push(conflictRecord(op, el, 'delete-vs-update',
          '元素在并发修改的同时被删除',
          '删除优先（可从冲突面板恢复元素）',
          { deletedSnapshot: snapshotOf(el) }));
      }
      el.deleted = true;
      bumpElementClock(el, op);
      break;
    }
    case 'restore': {
      const snap = op.data && op.data.element;
      if (!snap) break;
      const element = { ...snap, deleted: false, clock: {}, fieldClocks: snap.fieldClocks || {}, lastOp: null };
      state.elements.set(element.id, element);
      bumpElementClock(element, op);
      break;
    }
    case 'clear': {
      for (const element of state.elements.values()) {
        if (element.deleted) continue;
        if (isConcurrent(element, op)) {
          conflicts.push(conflictRecord({ ...op, elementId: element.id }, element, 'clear-vs-update',
            '清空画布操作与并发修改冲突',
            '清空优先（可从冲突面板恢复元素）',
            { deletedSnapshot: snapshotOf(element) }));
        }
        element.deleted = true;
        bumpElementClock(element, op);
      }
      break;
    }
    case 'restoreAll': {
      for (const snap of (op.data && op.data.elements) || []) {
        const element = { ...snap, deleted: false, clock: {}, fieldClocks: snap.fieldClocks || {}, lastOp: null };
        state.elements.set(element.id, element);
        bumpElementClock(element, op);
      }
      break;
    }
    default:
      break;
  }
  if (conflicts.length) state.conflicts.push(...conflicts);
  return conflicts;
}
