export class Outbox {
  constructor() {
    this.ops = [];
  }

  enqueue(op) {
    this.ops.push(op);
  }

  get size() {
    return this.ops.length;
  }

  peek(n) {
    return this.ops.slice(0, n);
  }

  ack(count) {
    this.ops.splice(0, count);
  }

  toJSON() {
    return this.ops;
  }

  static from(json) {
    const box = new Outbox();
    box.ops = Array.isArray(json) ? json : [];
    return box;
  }
}
