export function elementBBox(el) {
  switch (el.type) {
    case 'stroke': {
      let minX = 0; let minY = 0; let maxX = 0; let maxY = 0;
      for (const p of el.points || []) {
        minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
        minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
      }
      const pad = (el.strokeWidth || 2) / 2;
      return { x: el.x + minX - pad, y: el.y + minY - pad, w: maxX - minX + pad * 2, h: maxY - minY + pad * 2 };
    }
    case 'line': {
      const x = Math.min(el.x, el.x2);
      const y = Math.min(el.y, el.y2);
      return { x, y, w: Math.abs(el.x2 - el.x), h: Math.abs(el.y2 - el.y) };
    }
    case 'text': {
      const fs = el.fontSize || 20;
      const lines = String(el.text || '').split('\n');
      const w = Math.max(10, ...lines.map((l) => l.length)) * fs * 0.62;
      return { x: el.x, y: el.y, w, h: lines.length * fs * 1.3 };
    }
    default:
      return { x: el.x || 0, y: el.y || 0, w: el.w || 0, h: el.h || 0 };
  }
}

function center(el) {
  const b = elementBBox(el);
  return { x: b.x + b.w / 2, y: b.y + b.h / 2 };
}

function unrotate(el, px, py) {
  if (!el.rotation) return { x: px, y: py };
  const c = center(el);
  const cos = Math.cos(-el.rotation);
  const sin = Math.sin(-el.rotation);
  const dx = px - c.x;
  const dy = py - c.y;
  return { x: c.x + dx * cos - dy * sin, y: c.y + dx * sin + dy * cos };
}

function distToSegment(px, py, x1, y1, x2, y2) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  const len2 = dx * dx + dy * dy;
  let t = len2 === 0 ? 0 : ((px - x1) * dx + (py - y1) * dy) / len2;
  t = Math.max(0, Math.min(1, t));
  const cx = x1 + t * dx;
  const cy = y1 + t * dy;
  return Math.hypot(px - cx, py - cy);
}

export function hitTest(el, px, py) {
  const p = unrotate(el, px, py);
  const tol = Math.max(6, (el.strokeWidth || 2) / 2 + 3);
  switch (el.type) {
    case 'stroke': {
      const pts = el.points || [];
      for (let i = 1; i < pts.length; i += 1) {
        if (distToSegment(p.x, p.y, el.x + pts[i - 1].x, el.y + pts[i - 1].y, el.x + pts[i].x, el.y + pts[i].y) < tol) return true;
      }
      return pts.length === 1 && Math.hypot(p.x - el.x - pts[0].x, p.y - el.y - pts[0].y) < tol;
    }
    case 'line':
      return distToSegment(p.x, p.y, el.x, el.y, el.x2, el.y2) < tol;
    case 'ellipse': {
      const rx = (el.w || 1) / 2;
      const ry = (el.h || 1) / 2;
      const cx = el.x + rx;
      const cy = el.y + ry;
      const d = ((p.x - cx) ** 2) / (rx * rx) + ((p.y - cy) ** 2) / (ry * ry);
      if (el.fill && el.fill !== 'none') return d <= 1.05;
      return d <= 1.15 && d >= 0.8;
