import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { exec } from 'node:child_process';
import { WebSocketServer } from 'ws';
import { applyOp } from '../shared/merge.js';
import { RoomStore } from './store.js';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.join(__dirname, '..');

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.ico': 'image/x-icon',
};

export function startServer({ port = 3000, dataDir = path.join(ROOT, 'data', 'rooms'), open = false } = {}) {
  const store = new RoomStore(dataDir);
  const rooms = new Map();

  function roomPayload(room) {
    return {
      roomId: room.id,
      clock: room.state.clock,
      elements: [...room.state.elements.values()],
      conflicts: room.state.conflicts.slice(-500),
      opLog: room.opLog.slice(-2000),
      updatedAt: new Date().toISOString(),
    };
  }

  function getRoom(roomId) {
    let room = rooms.get(roomId);
    if (room) return room;
    room = {
      id: roomId,
      state: { elements: new Map(), clock: {}, conflicts: [] },
      opLog: [],
      clients: new Map(),
    };
    const saved = store.load(roomId);
    if (saved) {
      room.state.clock = saved.clock || {};
      room.state.conflicts = saved.conflicts || [];
      for (const el of saved.elements || []) room.state.elements.set(el.id, el);
      room.opLog = saved.opLog || [];
    }
    rooms.set(roomId, room);
    return room;
  }

  function persist(room) {
    store.schedule(room.id, () => roomPayload(room));
  }

  function broadcast(room, msg, except) {
    const raw = JSON.stringify(msg);
    for (const [ws] of room.clients) {
      if (ws !== except && ws.readyState === 1) ws.send(raw);
    }
  }

  function handleOp(room, ws, op) {
    const conflicts = applyOp(room.state, op);
    room.opLog.push({ ...op, appliedAt: Date.now() });
    persist(room);
    broadcast(room, { type: 'op', op, conflicts }, ws);
    return conflicts;
  }

  const server = http.createServer((req, res) => {
    const urlPath = decodeURIComponent((req.url || '/').split('?')[0]);
    let filePath;
    if (urlPath.startsWith('/shared/')) {
      filePath = path.join(ROOT, urlPath);
    } else {
      const rel = urlPath === '/' ? 'index.html' : urlPath.slice(1);
      filePath = path.join(ROOT, 'public', rel);
    }
    if (!path.resolve(filePath).startsWith(path.resolve(ROOT))) {
      res.writeHead(403);
      res.end();
      return;
    }
    fs.readFile(filePath, (err, data) => {
      if (err) {
        res.writeHead(404);
        res.end('not found');
        return;
      }
      res.writeHead(200, { 'Content-Type': MIME[path.extname(filePath)] || 'application/octet-stream' });
      res.end(data);
    });
  });

  const wss = new WebSocketServer({ server, path: '/ws' });
  wss.on('connection', (ws) => {
    let room = null;
    let user = null;
    ws.on('message', (raw) => {
      let msg;
      try {
        msg = JSON.parse(raw);
      } catch {
        return;
      }
      try {
        switch (msg.type) {
          case 'join': {
            room = getRoom(msg.roomId);
            user = msg.user;
            room.clients.set(ws, user);
            ws.send(JSON.stringify({
              type: 'snapshot',
              roomId: room.id,
              clock: room.state.clock,
              elements: [...room.state.elements.values()].filter((e) => !e.deleted),
              conflicts: room.state.conflicts,
              users: [...room.clients.values()],
            }));
            broadcast(room, { type: 'user-joined', user }, ws);
            break;
          }
          case 'op': {
            if (!room) break;
            const conflicts = handleOp(room, ws, msg.op);
            ws.send(JSON.stringify({ type: 'ack', opId: msg.op && msg.op.opId, conflicts }));
            break;
          }
          case 'sync': {
            if (!room || !Array.isArray(msg.ops)) break;
            const allConflicts = [];
            for (const op of msg.ops) allConflicts.push(...handleOp(room, ws, op));
            ws.send(JSON.stringify({ type: 'sync-ack', count: msg.ops.length, conflicts: allConflicts }));
            break;
          }
          case 'cursor': {
            if (!room || !user) break;
            broadcast(room, { type: 'cursor', userId: user.id, name: user.name, color: user.color, x: msg.x, y: msg.y }, ws);
            break;
          }
          default:
            break;
        }
      } catch (err) {
        ws.send(JSON.stringify({ type: 'error', message: String((err && err.message) || err) }));
      }
    });
    ws.on('close', () => {
      if (room && user) {
        room.clients.delete(ws);
        broadcast(room, { type: 'user-left', userId: user.id });
      }
    });
  });

  return new Promise((resolve) => {
    server.listen(port, () => {
      const address = server.address();
      const api = {
        port: address.port,
        server,
        wss,
        rooms,
        store,
        close: () => new Promise((res) => {
          for (const room of rooms.values()) {
            try {
              store.flush(room.id, () => roomPayload(room));
            } catch (err) {
              console.error('flush 失败:', err.message);
            }
          }
          wss.close();
          server.close(() => res());
        }),
      };
      if (open) openBrowser(`http://localhost:${address.port}`);
      resolve(api);
    });
  });
}

function openBrowser(url) {
  const cmd = process.platform === 'win32'
    ? `start "" "${url}"`
    : process.platform === 'darwin' ? `open "${url}"` : `xdg-open "${url}"`;
  exec(cmd, () => {});
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const port = Number(process.env.PORT || 3000);
  const open = !process.argv.includes('--no-open');
  startServer({ port, open }).then((api) => {
    console.log(`协作白板服务已启动: http://localhost:${api.port}`);
    console.log('WebSocket 端点: /ws');
    console.log(`数据目录: ${path.join(ROOT, 'data', 'rooms')}`);
    console.log('按 Ctrl+C 停止服务');
  });
  const shutdown = () => process.exit(0);
  process.on('SIGINT', shutdown);
  process.on('SIGTERM', shutdown);
}
